-- Journeys build plan J11 — step 7, the summary, handover, closing a contract.
-- Generated by `prisma migrate diff` from the applied lane database, then
-- hand-extended with the one CHECK Prisma cannot express. Nothing existing
-- changes: two nullable columns on Contract, three on ScopeItem, no backfill, so
-- no production data can be affected.
--
-- The CHECK is exercised by a direct insert in `j11.test.ts` (a handover on a
-- FEATURE, and a handover whose note is only whitespace).

-- AlterTable
ALTER TABLE "Contract" ADD COLUMN     "deliveredAt" TIMESTAMP(3),
ADD COLUMN     "deliveredById" TEXT;

-- AlterTable
ALTER TABLE "ScopeItem" ADD COLUMN     "handedOverAt" TIMESTAMP(3),
ADD COLUMN     "handedOverById" TEXT,
ADD COLUMN     "handoverNote" TEXT;

-- AddForeignKey
ALTER TABLE "Contract" ADD CONSTRAINT "Contract_deliveredById_fkey" FOREIGN KEY ("deliveredById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ScopeItem" ADD CONSTRAINT "ScopeItem_handedOverById_fkey" FOREIGN KEY ("handedOverById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Hand-written: only a deliverable is handed over, and the handover says what
-- was handed over. A page or a feature is delivered by the demo the customer
-- approves; a deliverable (the repository, the access, the export) has no demo,
-- and the record of its handover is the only record there is — so a note that is
-- NULL, empty or only whitespace is not one, stronger than `IS NOT NULL` as S2's
-- `FeedbackComment_declined_has_reason` is. An item not handed over has a NULL
-- `handedOverAt`, `NULL IS NULL` is true, and the CHECK passes for every row that
-- exists today. (`"kind" = 'DELIVERABLE'` is never NULL — the column is NOT NULL —
-- and `"handoverNote" IS NOT NULL AND …` is FALSE, not NULL, for a missing note,
-- so a handover with no note is refused rather than slipping through.)
ALTER TABLE "ScopeItem" ADD CONSTRAINT "ScopeItem_handover_is_a_deliverable" CHECK (
  "handedOverAt" IS NULL
  OR ("kind" = 'DELIVERABLE' AND "handoverNote" IS NOT NULL AND btrim("handoverNote") <> '')
);
